INSERT INTO public.invoicedocumenttext (id, controlnameid, languageid, languagetext) VALUES (148, 50, 1, 'Please be aware that your bank may deduct a fee or a percentage for international bank payments. The net amount to be received by HiTT should be in accordance with the total amount of this invoice. Thank you for you collaboration.');
INSERT INTO public.invoicedocumenttext (id, controlnameid, languageid, languagetext) VALUES (149, 50, 2, 'Tenga en cuenta que su banco podría deducir una comisión o un porcentaje por pagos internacionales. El importe neto que recibirá HiTT deberá coincidir con el importe total de esta factura. Gracias por su colaboración.');
INSERT INTO public.invoicedocumenttext (id, controlnameid, languageid, languagetext) VALUES (150, 50, 3, 'Tingueu en compte que el vostre banc pot deduir una comissió o un percentatge per pagaments bancaris internacionals. L''import net que rebrà HiTT hauria d''estar d''acord amb l''import total d''aquesta factura. Gràcies per la vostra col·laboració.');
INSERT INTO public.invoicedocumenttext (id, controlnameid, languageid, languagetext) VALUES (151, 51, 1, '<div>Good morning, I am sending the invoice number &#123;InvoiceCode&#125; regarding to our last conversation.</div>');
